const PBT_ENGINE = (() => {
  const IDX = {Q:0,DayPart:1,Mes:2,Semana:3,Tienda:4,Weekpart:5,Total:6,Espresso:7,CafeFiltrado:8,CBS:9,Food:10,Otro:11,Lobby:12,PickUpDelivery:13,DT:14};
  const SETS = {
    Q: PBT_QS,
    DayPart: PBT_DAYPARTS,
    Mes: PBT_MESES,
    Semana: PBT_SEMANAS,
    Tienda: PBT_TIENDAS,
    Weekpart: PBT_WEEKPARTS
  };
  function toIndexSet(field, values){
    if(!values || values.length === 0) return null;
    const list = SETS[field] || [];
    const s = new Set();
    values.forEach(v => {
      const i = list.indexOf(String(v));
      if(i >= 0) s.add(i);
    });
    return s;
  }
  function pct(part,total){
    if(!total || total <= 0) return 0;
    return Math.round((part / total) * 100);
  }
  function fix100(obj, keys){
    const total = keys.reduce((s,k)=>s+(Number(obj[k])||0),0);
    if(total === 0) return obj;
    if(total !== 100 && keys.length){
      obj[keys[0]] = (Number(obj[keys[0]])||0) + (100-total);
    }
    return obj;
  }
  function calculate(filters={}, tipo="CAFE"){
    const f = {
      Q: toIndexSet("Q", filters.Q),
      DayPart: toIndexSet("DayPart", filters.DayPart),
      Mes: toIndexSet("Mes", filters.Mes),
      Semana: toIndexSet("Semana", filters.Semana),
      Tienda: toIndexSet("Tienda", filters.Tienda),
      Weekpart: toIndexSet("Weekpart", filters.Weekpart)
    };
    const allowedStores = new Set((String(tipo).toUpperCase().includes("DT") ? TIENDAS_DT : TIENDAS_CAFE).map(t=>PBT_TIENDAS.indexOf(t)));
    const sum = {Total:0,Espresso:0,CafeFiltrado:0,CBS:0,Food:0,Otro:0,Lobby:0,PickUpDelivery:0,DT:0,Registros:0,Tiendas:new Set()};
    for(const r of PBT_DATA){
      if(f.Q && !f.Q.has(r[IDX.Q])) continue;
      if(f.DayPart && !f.DayPart.has(r[IDX.DayPart])) continue;
      if(f.Mes && !f.Mes.has(r[IDX.Mes])) continue;
      if(f.Semana && !f.Semana.has(r[IDX.Semana])) continue;
      if(f.Weekpart && !f.Weekpart.has(r[IDX.Weekpart])) continue;
      if(f.Tienda && !f.Tienda.has(r[IDX.Tienda])) continue;
      if(!allowedStores.has(r[IDX.Tienda])) continue;
      sum.Total += r[IDX.Total] || 0;
      sum.Espresso += r[IDX.Espresso] || 0;
      sum.CafeFiltrado += r[IDX.CafeFiltrado] || 0;
      sum.CBS += r[IDX.CBS] || 0;
      sum.Food += r[IDX.Food] || 0;
      sum.Otro += r[IDX.Otro] || 0;
      sum.Lobby += r[IDX.Lobby] || 0;
      sum.PickUpDelivery += r[IDX.PickUpDelivery] || 0;
      sum.DT += r[IDX.DT] || 0;
      sum.Registros++;
      sum.Tiendas.add(r[IDX.Tienda]);
    }
    const mix = fix100({
      Espresso:pct(sum.Espresso,sum.Total),
      "Café filtrado":pct(sum.CafeFiltrado,sum.Total),
      CBS:pct(sum.CBS,sum.Total),
      Food:pct(sum.Food,sum.Total),
      Otro:pct(sum.Otro,sum.Total)
    }, ["Espresso","Café filtrado","CBS","Food","Otro"]);
    const channelTotal = String(tipo).toUpperCase().includes("DT") ? (sum.Lobby + sum.PickUpDelivery + sum.DT) : (sum.Lobby + sum.PickUpDelivery);
    const canales = String(tipo).toUpperCase().includes("DT")
      ? fix100({Lobby:pct(sum.Lobby,channelTotal),"Pick up & Delivery":pct(sum.PickUpDelivery,channelTotal),DT:pct(sum.DT,channelTotal)}, ["Lobby","Pick up & Delivery","DT"])
      : fix100({Lobby:pct(sum.Lobby,channelTotal),"Pick up & Delivery":pct(sum.PickUpDelivery,channelTotal),DT:0}, ["Lobby","Pick up & Delivery"]);
    return {
      venta: Number(sum.Total.toFixed(2)),
      registros: sum.Registros,
      tiendasVisibles: sum.Tiendas.size,
      mix,
      canales
    };
  }
  return {IDX, calculate};
})();

